// Pressing the simulated button appends one more HIGH-then-LOW event at the
// right edge, so the reader can see the pattern extend without ever producing
// an intermediate voltage.
let nextSecond = chartData.labels.length;

function onAction(id) {
    if (id !== 'press') return;
    const set = chart.data.datasets[0];
    chart.data.labels.push(String(nextSecond++), String(nextSecond++));
    set.data.push(5, 0);
    // keep the window readable rather than growing without bound
    while (chart.data.labels.length > 21) {
        chart.data.labels.shift();
        set.data.shift();
    }
    chart.update();
}
